// Package brand is the install's branding: company, operator, and the two
// offers ("ventures") shown on the funnel, org and venture views. The values
// live in brand_gen.go, generated by scripts/tfg-brand.py from
// config/tfg/brand.yaml (or a client's brand file). Internal venture IDs stay
// the upstream slugs ("vantage", "launchpad-cohort") so upstream merges keep
// working; only labels change.
package brand

import "regexp"

// Venture is one offer as configured in the brand file.
type Venture struct {
	ID         string
	Label      string
	Kind       string
	Color      string
	Detail     string
	Focus      []string
	AreaAgents map[string][]string
}

var leadMatch = regexp.MustCompile(LeadMatch)

// LeadVenture routes a lead to an offer from its form or call text: the
// "vantage" slot when LeadMatch hits, else "launchpad-cohort".
func LeadVenture(text string) string {
	if leadMatch.MatchString(text) {
		return "vantage"
	}
	return "launchpad-cohort"
}

// Label is the display name for a venture slug (the slug itself if unknown).
func Label(id string) string {
	for _, v := range Ventures {
		if v.ID == id {
			return v.Label
		}
	}
	return id
}
